#!/usr/bin/env bash

has_all() {
    local file="$1" text
    shift
    for text in "$@"; do
        grep -qF -- "$text" "$file" || return 1
    done
}

all_chart_text() {
    cat "$CHART"/*.md
}

check_the_project_side_is_not_claimed_as_proved() {
    section "STAMPER.md and LIMITS.md: the project side is proved only once a cluster run has passed, and none is recorded"
    local sentence='The project side is proved only once a cluster run of the install in `INSTALL.md` has passed; none is recorded at this version.'
    t "STAMPER.md holds the conditional sentence" grep -qF "$sentence" "$CHART/STAMPER.md"
    t "LIMITS.md holds the conditional sentence" grep -qF "$sentence" "$CHART/LIMITS.md"
    t "no document says that the project side is proved before a run" test "$(all_chart_text | grep -ciE 'until then the project side is proved|project side is proved by')" -eq 0
    t "no document names a plan row or a battery" test "$(all_chart_text | grep -ciE '\(P[0-9]+\)|battery')" -eq 0
}

check_the_network_check_covers_the_namespaces_of_its_release() {
    section "the network check probes the namespaces of the release that holds it: none in the two-release install"
    local exact
    render nc_two_operator -f "$EXAMPLE" -f "$CHART/ci/platform-values.yaml" --set network_check.enabled=true
    render nc_single -f "$EXAMPLE" -f "$OPERATOR_VALUES" --set network_check.enabled=true
    t "operator release with namespaces [] and the check on: the ConfigMap of the system namespace lists no namespace" jqt nc_two_operator '[.[] | select(.kind == "ConfigMap" and .metadata.name == "br-sandbox-netcheck" and .metadata.namespace == "sbx-system") | .data.namespaces | gsub("\\s"; "")] == [""]'
    t "operator release with namespaces [] and the check on: no object br-sandbox-netcheck in any other namespace" jqt nc_two_operator '[.[] | select(.metadata.name == "br-sandbox-netcheck" and .metadata.namespace != null and .metadata.namespace != "sbx-system")] | length == 0'
    fails_with "BR_SANDBOX_OPERATOR_PART_REQUIRED{key=network_check}" -f "$EXAMPLE" -f "$CHART/ci/fence-values.yaml" --set network_check.enabled=true
    t "single release with the check on: the ConfigMap of the system namespace lists the four namespaces" jqt nc_single '[.[] | select(.kind == "ConfigMap" and .metadata.name == "br-sandbox-netcheck" and .metadata.namespace == "sbx-system") | .data.namespaces | split("\n") | map(select(length > 0))] | map(length) == [4]'
    t "single release with the check on: each of the four namespaces holds the ConfigMap, the Role and the RoleBinding br-sandbox-netcheck" jqt nc_single '[.[] | select(.metadata.name == "br-sandbox-netcheck" and .metadata.namespace != null and .metadata.namespace != "sbx-system") | .kind] | sort | group_by(.) | map(length) == [4, 4, 4]'
    exact='In the two-release install, chart 0.4.0 runs no network check of a sandbox namespace. In that shape nothing of the chart proves on the cluster that the network plugin enforces the policies of a sandbox namespace. The fence check of the keeper proves the names and the shape, not the enforcement.'
    t "INSTALL.md carries the exact sentences" grep -qF "$exact" "$CHART/INSTALL.md"
    t "LIMITS.md carries the exact sentences" grep -qF "$exact" "$CHART/LIMITS.md"
    t "LIMITS.md says the key namespaces of the ConfigMap is empty and no probe pod starts" grep -qF 'the key `namespaces` of its ConfigMap is empty, no probe pod starts' "$CHART/LIMITS.md"
    t "the README states the limit where it describes the probe pod of each namespace and names the route" grep -qF 'so the check probes no sandbox namespace there (the key `namespaces` of its ConfigMap is empty and no probe pod starts), and the fence release cannot turn the check on' "$CHART/README.md"
    t "no document says another route without naming it" test "$(all_chart_text | grep -ciE 'by another route|check them by')" -eq 0
}

check_the_netcheck_route_renders_the_check_of_one_probe_namespace() {
    section "the route of INSTALL.md: four steps, one probe namespace in the operator release, a new Job for the check"
    local one="$CHART/ci/netcheck-route-values.yaml" run="$CHART/ci/netcheck-route-run-values.yaml" pool probe sentence
    local step1 step3 step4
    step1=$'helm upgrade <release> <chart> \\\n  -f <install-values> \\\n  -f <route-values> \\\n  --set crds.install=true'
    step3=$'helm upgrade <release> <chart> \\\n  -f <install-values> \\\n  -f <route-values> \\\n  -f <route-run-values> \\\n  --set crds.install=true'
    step4=$'kubectl delete sandboxpool pool -n <scope>-netcheck\nhelm upgrade <release> <chart> \\\n  -f <install-values> \\\n  --set crds.install=true'
    yq '.render_namespace = false' "$EXAMPLE" >"$WORK/example-no-namespace.yaml"
    yq 'del(.render_namespace)' "$one" >"$WORK/route-without-namespace.yaml"
    render route_off -f "$WORK/example-no-namespace.yaml" -f "$CHART/ci/platform-values.yaml" -f "$one"
    render route_on -f "$WORK/example-no-namespace.yaml" -f "$CHART/ci/platform-values.yaml" -f "$one" -f "$run"
    render route_no_namespace -f "$WORK/example-no-namespace.yaml" -f "$CHART/ci/platform-values.yaml" -f "$WORK/route-without-namespace.yaml"
    t "the base values of steps 1 and 3 render no Namespace by themselves: render_namespace is false there" test "$(yq '.render_namespace' "$WORK/example-no-namespace.yaml")" = false
    t "without render_namespace in the route file no Namespace of the probe namespace is rendered, so the Namespace cases of steps 1 and 3 depend on the route file" jqt route_no_namespace '[.[] | select(.kind == "Namespace" and .metadata.name == "sbx-alpha-netcheck")] | length == 0'
    render route_removed -f "$EXAMPLE" -f "$CHART/ci/platform-values.yaml"
    yq 'del(.namespaces)' "$one" >"$WORK/route-without-list.yaml"
    yq '.namespaces += [{"name": "sbx-alpha-netcheck", "mode": "none"}]' "$EXAMPLE" >"$WORK/example-appended.yaml"
    render route_install_only -f "$EXAMPLE" -f "$OPERATOR_VALUES"
    render route_replaced -f "$EXAMPLE" -f "$OPERATOR_VALUES" -f "$one"
    render route_appended -f "$WORK/example-appended.yaml" -f "$OPERATOR_VALUES" -f "$WORK/route-without-list.yaml" -f "$run"
    render route_fence -f "$EXAMPLE" -f "$CHART/ci/fence-values.yaml"
    yq '.namespaces += [{"name": "sbx-alpha-netcheck", "mode": "none"}]' "$EGRESS_VALUES" >"$WORK/egress-appended.yaml"
    t "step 1 file: one namespace of mode none, the Namespace rendered, the check off, three keys" test "$(yq -o=json -I=0 '[[.namespaces[] | .name + "/" + .mode], .render_namespace, .network_check.enabled, (keys | length)]' "$one")" = '[["sbx-alpha-netcheck/none"],true,false,3]'
    t "step 3 file: the check on, a new run_id and one target, nothing else" test "$(yq -o=json -I=0 '[.network_check.enabled, .network_check.run_id, (.network_check.targets | length), (keys | length), (.network_check | keys | length)]' "$run")" = '[true,"route-1",1,1,3]'
    t "the probe namespace matches a scope of the fixture" test "$(yq '.scopes | keys | .[]' "$EXAMPLE" | grep -c '^sbx-alpha$')" -eq 1
    t "step 1 renders no Job and no CronJob" jqt route_off '[.[] | select(.kind == "Job" or .kind == "CronJob")] | length == 0'
    t "step 1 renders the Namespace of the probe namespace with the managed labels and the mode none" jqt route_off '[.[] | select(.kind == "Namespace" and .metadata.name == "sbx-alpha-netcheck") | .metadata.labels | select(.["br.sandbox/managed"] == "true" and .["br.sandbox/mode"] == "none")] | length == 1'
    t "step 1 renders the fence objects of the probe namespace and no object br-sandbox-netcheck there" jqt route_off '([.[] | select(.metadata.namespace == "sbx-alpha-netcheck") | .kind] | contains(["ResourceQuota", "LimitRange", "NetworkPolicy", "ServiceAccount", "RoleBinding"])) and ([.[] | select(.metadata.name == "br-sandbox-netcheck")] | length == 0)'
    t "step 3 renders the Namespace of the probe namespace with the managed labels and the mode none" jqt route_on '[.[] | select(.kind == "Namespace" and .metadata.name == "sbx-alpha-netcheck") | .metadata.labels | select(.["br.sandbox/managed"] == "true" and .["br.sandbox/mode"] == "none")] | length == 1'
    t "step 3 renders one Job, named with the run_id, in the system namespace, and not the Job of the first install" jqt route_on '[.[] | select(.kind == "Job") | .metadata.name + "/" + .metadata.namespace] == ["br-sandbox-netcheck-route-1/sbx-system"]'
    t "the first install (the example values with the operator release) renders another Job name than step 3" test "$(jqv route_removed '[.[] | select(.kind == "Job") | .metadata.name] | join(",")')" = br-sandbox-netcheck-initial -a "$(jqv route_on '[.[] | select(.kind == "Job") | .metadata.name] | join(",")')" = br-sandbox-netcheck-route-1
    t "step 3 renders the ConfigMap, the Role and the RoleBinding br-sandbox-netcheck in the probe namespace" jqt route_on '[.[] | select(.metadata.name == "br-sandbox-netcheck" and .metadata.namespace == "sbx-alpha-netcheck") | .kind] | sort == ["ConfigMap", "Role", "RoleBinding"]'
    t "step 3 lists the probe namespace and no other in the ConfigMap of the system namespace, with the target of the run file" jqt route_on '[.[] | select(.kind == "ConfigMap" and .metadata.name == "br-sandbox-netcheck" and .metadata.namespace == "sbx-system") | [(.data.namespaces | split("\n") | map(select(length > 0))), (.data["extra-targets"] | split("\n") | map(select(length > 0)))]] == [[["sbx-alpha-netcheck none"], ["192.0.2.10:5432"]]]'
    t "step 3 renders the third NetworkPolicy of the system namespace, br-sandbox-egress-netcheck, and step 1 does not" test "$(jqv route_on '[.[] | select(.kind == "NetworkPolicy" and .metadata.namespace == "sbx-system") | .metadata.name] | sort | join(",")')" = br-sandbox-default-deny,br-sandbox-egress-keeper,br-sandbox-egress-netcheck -a "$(jqv route_off '[.[] | select(.kind == "NetworkPolicy" and .metadata.namespace == "sbx-system") | .metadata.name] | sort | join(",")')" = br-sandbox-default-deny,br-sandbox-egress-keeper
    t "step 4 (no route file) renders no probe namespace, and renders the Job of the first install with an empty list of namespaces" jqt route_removed '([.[] | select(.metadata.namespace == "sbx-alpha-netcheck" or (.kind == "Namespace" and .metadata.name == "sbx-alpha-netcheck"))] | length == 0) and ([.[] | select(.kind == "ConfigMap" and .metadata.name == "br-sandbox-netcheck" and .metadata.namespace == "sbx-system") | .data.namespaces | gsub("\\s"; "")] == [""])'
    t "the Job of step 3 is in the system namespace, no Job or CronJob is in the probe namespace, and the install values do not render that Job" test "$(jqv route_on '[.[] | select(.kind == "Job" and .metadata.name == "br-sandbox-netcheck-route-1") | .metadata.namespace] | join(",")')" = sbx-system -a "$(jqv route_on '[.[] | select((.kind == "Job" or .kind == "CronJob") and .metadata.namespace == "sbx-alpha-netcheck")] | length')" -eq 0 -a "$(jqv route_removed '[.[] | select(.metadata.name == "br-sandbox-netcheck-route-1")] | length')" -eq 0
    t "INSTALL.md step 4 says that the Job of the route is in the system namespace and not in the probe namespace, and that the upgrade removes it because the install values do not render it" grep -qF 'The upgrade removes the probe namespace and the objects that the release rendered in it. The Job `br-sandbox-netcheck-route-1` is in the system namespace, not in the probe namespace; the upgrade removes it too, because the install values do not render it.' "$CHART/INSTALL.md"
    t "INSTALL.md step 1 says to keep a backup of the install values before the probe entry is appended, and that step 4 passes the backup as the install values, before the sentence that appends the entry" test "$(grep -cF 'If they list namespaces, this is the order. Keep a backup of the install values before you append the probe entry; step 4 passes the backup as `<install-values>`. Then delete the `namespaces` key from `<route-values>` and append the entry' "$CHART/INSTALL.md")" -eq 1
    t "INSTALL.md step 4 uses the backup of step 1 only if step 1 made one, and uses the install values as they are if they list no namespace" test "$(grep -cF '**Step 4: removal.** If step 1 made a backup of the install values, use the backup. If the install values list no namespace, step 1 appended nothing, and step 4 uses the install values as they are. Delete the `SandboxPool` first,' "$CHART/INSTALL.md")" -eq 1 -a "$(grep -cF 'Keep a backup of the install values' "$CHART/INSTALL.md")" -eq 1
    t "INSTALL.md step 4 says, before its command, that the install values of the command are those without the probe entry: the backup if step 1 made one, else the install values as they are" test "$(grep -cF 'which probes no namespace. In the command of this step, `<install-values>` is the install values without the probe entry: the backup of step 1 if step 1 made one, else your install values as they are.' "$CHART/INSTALL.md")" -eq 1 -a "$(grep -n 'In the command of this step, `<install-values>`' "$CHART/INSTALL.md" | cut -d: -f1)" -lt "$(grep -n '^kubectl delete sandboxpool' "$CHART/INSTALL.md" | cut -d: -f1)"
    t "INSTALL.md step 1 says that a route with no listed namespace appends nothing, and the word copy names only the route copy in the route section" test "$(grep -cF 'use the route copy as it is, and step 1 appends nothing.' "$CHART/INSTALL.md")" -eq 1 -a "$(sed -n '/^\*\*Step 1: the probe namespace/,/^\*\*Step 4: removal/p' "$CHART/INSTALL.md" | grep -oE '(the|a|that|this) copy' | wc -l | tr -d ' ')" -eq 0
    t "INSTALL.md no longer says that the probe namespace holds the Job" test "$(grep -cF 'and everything in it, the Job' "$CHART/INSTALL.md")" -eq 0
    t "the chart does not refuse the check with no target at render time: the script fails alone" test "$(helm template t "$CHART" -f "$EXAMPLE" -f "$CHART/ci/platform-values.yaml" -f "$one" -f "$run" --set-json 'network_check.targets=[]' >/dev/null 2>&1; echo $?)" = 0
    t "INSTALL.md carries the line that the script prints for a missing class targets" grep -qF '{"net":"cluster","mode":"all","target":"targets","kind":"target_class","expected":"present","observed":"missing","control":"ok"}' "$CHART/INSTALL.md"
    t "the script prints that line for each missing class, and names targets as the first class" has_all "$CHART/files/network-check.sh" '"kind":"target_class","expected":"present","observed":"missing","control":"ok"}' 'for class in targets node_kubelet'
    t "no namespace of the fence release of the install is in any step of the route" jqt route_on '[.[] | (.metadata.namespace // "") , (if .kind == "Namespace" then .metadata.name else "" end)] | map(select(. == "sbx-alpha-none" or . == "sbx-alpha-allow" or . == "sbx-alpha-full" or . == "sbx-beta-none")) | length == 0'
    t "no object of the fence release has the kind, namespace and name of an object of step 1 or of step 3" test "$(jq -rn --slurpfile a "$WORK/route_off.json" --slurpfile c "$WORK/route_on.json" --slurpfile b "$WORK/route_fence.json" '[($a[0] + $c[0])[] | [.kind, (.metadata.namespace // ""), .metadata.name] | join("/")] as $x | [$b[0][] | [.kind, (.metadata.namespace // ""), .metadata.name] | join("/")] | map(select(. as $y | $x | index($y))) | length')" -eq 0
    t "helm lint --strict passes on step 1" helm lint --strict "$CHART" -f "$EXAMPLE" -f "$CHART/ci/platform-values.yaml" -f "$one"
    t "helm lint --strict passes on step 3" helm lint --strict "$CHART" -f "$EXAMPLE" -f "$CHART/ci/platform-values.yaml" -f "$one" -f "$run"
    t "the CI lint loop names both route files" grep -qF 'stamper netcheck-route netcheck-route-run; do' "$ROOT/.github/workflows/ci.yml"
    t "INSTALL.md names the command of step 1: the install values, the copy of the route file and crds.install, with placeholders" test "$(install_block 5)" = "$step1"
    t "INSTALL.md names the command of step 3: the install values, the two route copies and crds.install, with placeholders" test "$(install_block 8)" = "$step3"
    t "INSTALL.md names the two commands that wait for the Job of the route and read its logs, with the Job name that step 3 renders and the system namespace as a placeholder" test "$(install_block 9)" = $'kubectl wait --for=condition=complete job/br-sandbox-netcheck-route-1 -n <system-namespace> --timeout=10m\nkubectl logs job/br-sandbox-netcheck-route-1 -n <system-namespace>'
    t "the Job of those commands is named after the run_id of the run file, and is rendered in the system namespace of the release" test "$(yq '.network_check.run_id' "$run")" = route-1 -a "$(jqv route_on '[.[] | select(.kind == "Job") | .metadata.name + "/" + .metadata.namespace] | join(",")')" = br-sandbox-netcheck-route-1/sbx-system
    t "INSTALL.md says what <system-namespace> is, and that the Job is in it and not in the probe namespace" grep -qF -- '- `<system-namespace>`: the system namespace of the release: `{prefix}-system` (`installation.namespace_prefix`), or `installation.system_namespace` when it is set (`sbx-system` with the fixture values). The Job of the check and its pod are in it, and not in the probe namespace (step 3).' "$CHART/INSTALL.md"
    t "INSTALL.md says that a Job that fails never becomes complete, so a timeout is not a verdict" grep -qF 'a Job that fails never becomes `complete`, so a timeout is not a verdict: read the logs and the status of the Job.' "$CHART/INSTALL.md"
    t "INSTALL.md step 1 removes the Job of the first install only if the install values rendered it" grep -qF 'If the install values rendered the Job `br-sandbox-netcheck-initial` (the fixture values do), this upgrade also removes it.' "$CHART/INSTALL.md"
    t "INSTALL.md no longer says that the operator release always has an empty list of namespaces" test "$(grep -cF 'The operator release above has `namespaces: []`, and' "$CHART/INSTALL.md")" -eq 0
    t "INSTALL.md says that the one list of namespaces is appended to the install values and that a second list replaces the first" has_all "$CHART/INSTALL.md" 'In Helm a later `-f` file replaces a list of an earlier file; it does not merge the two.' 'delete the `namespaces` key from `<route-values>` and append the entry `{name: <scope>-netcheck, mode: none}` to the `namespaces` list of the install values' 'a second list would remove the other namespaces from the release' 'with `true` the release renders the Namespace of every entry of `namespaces`, not only that of the probe namespace'
    t "the route file passed as a second file replaces the list of the install values: the namespaces of the install values are gone from the render" test "$(jqv route_replaced '[.[] | select(.metadata.namespace == "sbx-alpha-none")] | length')" -eq 0 -a "$(jqv route_install_only '[.[] | select(.metadata.namespace == "sbx-alpha-none")] | length')" -gt 0
    t "with the probe entry appended to the list of the install values and no namespaces key in the route file, the namespaces of the install values stay, the probe namespace is added and the Job is rendered" jqt route_appended '([.[] | select(.metadata.namespace == "sbx-alpha-none")] | length > 0) and ([.[] | select(.kind == "Namespace" and .metadata.name == "sbx-alpha-netcheck")] | length == 1) and ([.[] | select(.kind == "Job") | .metadata.name] == ["br-sandbox-netcheck-route-1"])'
    t "the route file without its namespaces key holds the other keys of the route file only" test "$(yq 'keys | sort | join(",")' "$WORK/route-without-list.yaml")" = 'network_check,render_namespace'
    t "INSTALL.md names the commands of step 4: the pool is deleted first, then the upgrade has the install values and no route copy" test "$(install_block 10)" = "$step4"
    t "no command of the four steps names a file of ci/" test "$(for n in 5 6 7 8 9 10; do install_block "$n"; done | grep -c "ci/")" -eq 0
    t "every placeholder of the commands of the four steps is explained in the list before step 1" test "$(for n in 5 6 7 8 9 10; do install_block "$n"; done | grep -oE "<[a-z-]+>" | sort -u | while read -r token; do grep -E "^- \`<" "$CHART/INSTALL.md" | grep -qF -- "$token" || echo "$token"; done | wc -l | tr -d " ")" -eq 0 -a "$(for n in 5 6 7 8 9 10; do install_block "$n"; done | grep -oE "<[a-z-]+>" | sort -u | tr "
" " ")" = "<chart> <image> <install-values> <release> <route-run-values> <route-values> <scope> <size> <system-namespace> "
    t "the list of placeholders comes before step 1" test "$(grep -n "^The commands of the four steps use these placeholders" "$CHART/INSTALL.md" | cut -d: -f1)" -lt "$(grep -n "^\*\*Step 1:" "$CHART/INSTALL.md" | cut -d: -f1)"
    t "the list of placeholders names the probe namespace, the scope table, the target and the pool values" has_all "$CHART/INSTALL.md" "- \`<scope>\`: a key of the table \`scopes\` of the install values. The probe namespace is \`<scope>-netcheck\`." "- \`<host>:<port>\`: the target that the owner chooses (step 3)." "- \`<image>\` and \`<size>\`: the image and the size of the pool of the probe namespace (step 2)." "- \`<release>\`: the name of the operator release" "- \`<chart>\`: the path of the chart folder, or the chart reference" "- \`<install-values>\`: a values file of the operator release"
    t "INSTALL.md says to copy each route file to a file of the owner and to replace the namespace name and the target in the route copy" has_all "$CHART/INSTALL.md" "Copy \`ci/netcheck-route-values.yaml\` to a file of the owner, \`<route-values>\`, and replace the namespace name in the route copy: \`sbx-alpha-netcheck\` becomes \`<scope>-netcheck\`." "Copy \`ci/netcheck-route-run-values.yaml\` to a file of the owner, \`<route-run-values>\`, and replace the target \`192.0.2.10:5432\` in the route copy by \`<host>:<port>\`."
    t "INSTALL.md says that a name whose prefix is not a scope fails with BR_SANDBOX_NO_SCOPE" grep -qF "A name whose prefix is not a scope of the table \`scopes\` of the install values fails the render with \`BR_SANDBOX_NO_SCOPE{namespace=...}\` (tested offline)." "$CHART/INSTALL.md"
    fails_with "BR_SANDBOX_NO_SCOPE{namespace=other-netcheck}" -f "$EXAMPLE" -f "$CHART/ci/platform-values.yaml" --set-json 'namespaces=[{"name":"other-netcheck","mode":"none"}]'
    t "INSTALL.md says that the offline tests give the placeholders the fixtures as values" grep -qF "The offline tests render each step and lint it, with the fixtures as the values: \`<install-values>\` are \`ci/example-values.yaml\` and \`ci/platform-values.yaml\`, \`<route-values>\` and \`<route-run-values>\` are the two files of \`ci/\` as they are, \`<scope>\` is \`sbx-alpha\`" "$CHART/INSTALL.md"
    pool="$(install_block 6 | yq -o=json -I=0 '.')"
    t "the pool of step 2 holds the placeholders of the namespace, the image and the size" test "$(jq -c '[.metadata.namespace, .spec.image, .spec.size]' <<<"$pool")" = '["<scope>-netcheck","<image>","<size>"]'
    pool="$(jq -c --argjson size "$(install_block 4 | yq -o=json -I=0 '.spec.size')" '.metadata.namespace = "sbx-alpha-netcheck" | .spec.image = "registry.example.test/agents/base:1.0" | .spec.size = $size' <<<"$pool")"
    t "the pool of step 2 is one SandboxPool of the probe namespace with minReplicas 0, maxReplicas 1, margin 0, and only keys of the definition" test "$(jq -c '[.kind, .metadata.namespace, .spec.minReplicas, .spec.maxReplicas, .spec.margin, ((.spec | keys) - ["image", "size", "minReplicas", "maxReplicas", "margin", "refillSeconds", "floors"] | length)]' <<<"$pool")" = '["SandboxPool","sbx-alpha-netcheck",0,1,0,0]'
    t "the pool of step 2 sets the four fields that keeper 0.2.0 requires" test "$(jq '.spec | has("image") and has("size") and has("minReplicas") and has("maxReplicas")' <<<"$pool")" = true
    render_yaml route_on_yaml -f "$EXAMPLE" -f "$CHART/ci/platform-values.yaml" -f "$one" -f "$run"
    probe="$(probe_pod route_on sbx-alpha-netcheck | jq -c .)"
    t "the probe pod of the check is admitted by the pod policy model with the pool of step 2, and refused with no pool" test "$(verdict route_on CREATE pods "$(jq -c '.' <<<"$probe")" null "[$(jq -c '.' <<<"$pool")]")" = admit -a "$(verdict route_on CREATE pods "$(jq -c '.' <<<"$probe")" null '[]')" = PARAMETER_NOT_FOUND
    t "INSTALL.md carries the refusal text that a reader sees when the pool is missing" grep -qF 'The pods "br-sandbox-netcheck-probe" is invalid: ValidatingAdmissionPolicy '"'"'br-sandbox-pod'"'"' with binding '"'"'br-sandbox-pod'"'"' denied request: failed to configure binding: no params found for policy binding with Deny parameterNotFoundAction' "$CHART/INSTALL.md"
    t "INSTALL.md says that a Job with an empty list of namespaces exits 0 and proves nothing" grep -qF 'A Job with an empty `namespaces` list exits 0 and proves nothing' "$CHART/INSTALL.md"
    t "INSTALL.md says that the probe namespace holds one SandboxPool at 0 replicas for the time of the check" grep -qF 'The probe namespace holds one `SandboxPool` at 0 replicas for the time of the check.' "$CHART/INSTALL.md"
    t "INSTALL.md says that the pool has minReplicas 0 and margin 0 so that no warm pod starts, and what the default margin gives" has_all "$CHART/INSTALL.md" 'The pool has `minReplicas: 0`, `maxReplicas: 1` and `margin: 0`.' 'the default margin is 2, and with it a pool of `minReplicas: 0` and `maxReplicas: 1` gets one warm pod'
    t "INSTALL.md says that a Job that ran is not run again and that the check is a new Job each time" grep -qF 'A Job that ran is not run again, so the check is a new Job each time (a new `network_check.run_id`).' "$CHART/INSTALL.md"
    t "INSTALL.md says that the class targets needs one entry and what a target is" grep -qF 'The class `targets` of the Job needs at least one entry. A target is a `host:port` that the Job pod reaches' "$CHART/INSTALL.md"
    t "INSTALL.md says that the second upgrade adds the third network policy of the system namespace" grep -qF 'a third NetworkPolicy in the system namespace, `br-sandbox-egress-netcheck`' "$CHART/INSTALL.md"
    t "INSTALL.md step 3 carries the sentence that the second upgrade passes the install values and the two route copies" test "$(sed -n '/^\*\*Step 3: the check, as a new Job/p' "$CHART/INSTALL.md" | grep -cF 'Upgrade again with the install values and the two route copies.')" -eq 1
    sentence='When this route has been run on a cluster and the Job reports no mismatch, it proves on that cluster that the network plugin enforces the default-deny policy of the chart, and that no rule of the cluster opens a namespace with this name. This repository records no such run at this version.'
    t "INSTALL.md and LIMITS.md carry the conditional proof sentence" test "$(grep -cF "$sentence" "$CHART/INSTALL.md" "$CHART/LIMITS.md" | grep -c ':1$')" -eq 2
    t "INSTALL.md and LIMITS.md say what the route does not probe and what it proves for the entries of the modes allow and full" test "$(grep -cF 'It does not probe a namespace of a project that `namespaces` does not list, or a fence that the stamper made. For an entry of `namespaces` in the mode `allow` or `full` (the install values may list some), the Job proves the refusal of the targets that it probes there; for an entry in mode `allow` when `egress.enabled` is `true`, it also proves the refusal of a `CONNECT` through the proxy to each target and to the off-list host. It does not prove the allowed traffic of the modes `allow` and `full`, and the checks of that traffic on a real cluster are not this Job.' "$CHART/INSTALL.md" "$CHART/LIMITS.md" | grep -c ':1$')" -eq 2
    t "no document says any more that the route does not probe the modes allow and full" test "$(all_chart_text | grep -cF 'It does not probe a namespace of a project, the modes')" -eq 0
    render route_appended_egress -f "$EXAMPLE" -f "$WORK/egress-appended.yaml" -f "$OPERATOR_VALUES" -f "$WORK/route-without-list.yaml" -f "$run"
    t "the Job probes every entry of the list in its own mode, the modes allow and full of the install values included, and marks the CONNECT path of the entry in mode allow only" test "$(jqv route_appended_egress '[.[] | select(.kind == "ConfigMap" and .metadata.name == "br-sandbox-netcheck" and .metadata.namespace == "sbx-system") | .data.namespaces | split("\n")[] | select(. != "")] | sort | join(",")')" = 'sbx-alpha-allow allow proxy,sbx-alpha-full full,sbx-alpha-netcheck none,sbx-alpha-none none,sbx-beta-none none'
    t "the script probes every line of the namespaces file, and sends the CONNECT lines for the path proxy only, to each target and, in mode allow, to the off-list host" has_all "$CHART/files/network-check.sh" 'done <"$dir/namespaces"' 'if [ "$path" = proxy ]; then' 'if [ "$2" = allow ]; then' 'offlist=$(cat "$dir/offlist-host")'
    t "INSTALL.md says that the install values list internal_cidrs with the link-local range or a cover of it, else each helm command stops with BR_SANDBOX_LINK_LOCAL_MISSING" grep -qF 'If the install values set `network.internal_cidrs`, the list must hold `169.254.0.0/16` or an entry that covers it (a well-formed IPv4 CIDR), else each `helm` command of the route stops at the render with `BR_SANDBOX_LINK_LOCAL_MISSING`.' "$CHART/INSTALL.md"
    fails_with 'BR_SANDBOX_LINK_LOCAL_MISSING{key=network.internal_cidrs,range=169.254.0.0/16}' -f "$EXAMPLE" -f "$OPERATOR_VALUES" -f "$one" --set 'network.internal_cidrs={10.0.0.0/8}'
    t "step 1 renders with install values whose network.internal_cidrs holds the range, or a cover of it" bash -c 'helm template t "$1" -f "$2" -f "$3" -f "$4" --set "network.internal_cidrs={10.0.0.0/8,169.254.0.0/16}" >/dev/null && helm template t "$1" -f "$2" -f "$3" -f "$4" --set "network.internal_cidrs={10.0.0.0/8,169.254.0.0/15}" >/dev/null' _ "$CHART" "$EXAMPLE" "$OPERATOR_VALUES" "$one"
    t "INSTALL.md puts the paragraph on one list of namespaces before the paragraph that upgrades, and step 1 no longer says Then upgrade before it" test "$(grep -n '^\*\*One list of namespaces, not two' "$CHART/INSTALL.md" | cut -d: -f1)" -lt "$(grep -n '^\*\*Upgrade of step 1' "$CHART/INSTALL.md" | cut -d: -f1)" -a "$(grep -n '^\*\*Upgrade of step 1' "$CHART/INSTALL.md" | cut -d: -f1)" -lt "$(grep -n '^helm upgrade <release> <chart>' "$CHART/INSTALL.md" | head -1 | cut -d: -f1)" -a "$(grep -cF 'so the release renders no Job and no Job fails before a pool exists. Before the upgrade, read the next paragraph: if the install values list namespaces, the owner removes the `namespaces` key from the route copy.' "$CHART/INSTALL.md")" -eq 1 -a "$(grep '^\*\*Step 1:' "$CHART/INSTALL.md" | grep -c 'Then upgrade')" -eq 0
    t "INSTALL.md carries the sentence that upgrades after the list paragraph, and the removal of the Job of the first install" grep -qF '**Upgrade of step 1.** Then upgrade the operator release with the install values and the route copy, the route copy being as the paragraph above leaves it. If the install values rendered the Job `br-sandbox-netcheck-initial` (the fixture values do), this upgrade also removes it.' "$CHART/INSTALL.md"
    t "INSTALL.md tells the reader to save the pool as pool.yaml, and to create it after step 1 and before step 3, with the command of the block that follows the pool" has_all "$CHART/INSTALL.md" 'Save the object below as the file `pool.yaml`, with the three placeholders replaced, and create the pool with the command under it, after step 1 and before step 3.'
    t "the command that creates the pool is kubectl apply of the file that the text names, and its object is the pool that step 4 deletes" test "$(install_block 7)" = 'kubectl apply -f pool.yaml' -a "$(install_block 6 | yq '.metadata.name')" = pool -a "$(install_block 6 | yq '.kind')" = SandboxPool -a "$(install_block 10 | grep -c '^kubectl delete sandboxpool pool -n <scope>-netcheck$')" -eq 1
    t "INSTALL.md says that the log of the Job can hold Warning lines that are not result lines, marks that as reported with no record, and says what a result line is" grep -qF 'The log can hold lines that start with `Warning:` (for example about Pod Security) that `kubectl` prints (reported by the operator of a test cluster; no record in this repository; not proved here); they are not result lines, and the script prints no `Warning` line. The result lines are the lines that the script prints, each one a JSON object that starts with `{"net":`.' "$CHART/INSTALL.md"
    t "every line that the script prints with a kind is a JSON object that starts with the key net, and the script prints no Warning line" test "$(grep -F 'printf' "$CHART/files/network-check.sh" | grep -cF '"kind"')" -ge 6 -a "$(grep -F 'printf' "$CHART/files/network-check.sh" | grep -F '"kind"' | grep -cvF "printf '{\"net\":")" -eq 0 -a "$(grep -c 'Warning' "$CHART/files/network-check.sh")" -eq 0
    t "no document states the proof in the present tense, and none names a platform test" test "$(all_chart_text | grep -ciE 'It proves on this cluster|made by the platform test|the platform test')" -eq 0
    t "INSTALL.md says that no step was run by the tests of this repository" grep -qF 'no step was run on a cluster by the tests of this repository at this version' "$CHART/INSTALL.md"
    t "INSTALL.md says that the operator install with the fixture values renders the check Job, its ServiceAccount, its ClusterRole and the policy of the system namespace" grep -qF 'the command also renders the check Job `br-sandbox-netcheck-initial`, its ServiceAccount, its ClusterRole and the NetworkPolicy `br-sandbox-egress-netcheck` in the system namespace' "$CHART/INSTALL.md"
    t "the first install of the fixtures renders that Job, its ServiceAccount, its ClusterRole and the policy" jqt route_removed '([.[] | select(.kind == "Job") | .metadata.name] == ["br-sandbox-netcheck-initial"]) and ([.[] | select(.metadata.name == "br-sandbox-netcheck" and (.kind == "ServiceAccount" or .kind == "ClusterRole"))] | length == 1) and ([.[] | select(.kind == "ClusterRole" and (.metadata.name | endswith("-netcheck")))] | length == 1) and ([.[] | select(.kind == "NetworkPolicy" and .metadata.name == "br-sandbox-egress-netcheck")] | length == 1)'
    t "no document says that a cluster run was observed with no record: each claim from a cluster run is marked as reported, not recorded, not proved here" test "$(all_chart_text | grep -ciE 'observed once|one cluster run reported|the tested install|tested install')" -eq 0
}

check_the_changelog_040_holds_the_values_the_behaviour_and_the_faults() {
    section "the CHANGELOG 0.4.0 lists the moved values, the pod policy at an update and every new fault"
    local text code
    text="$(changelog_040)"
    t "it says that pool.size becomes limits.size and pool.max_sandboxes becomes limits.pods" grep -qF '`pool.size` becomes `limits.size` and `pool.max_sandboxes` becomes `limits.pods`' <<<"$text"
    t "the schema refuses pool.size and pool.max_sandboxes" bash -c '! helm template t "$1" -f "$2" --set pool.max_sandboxes=3 >/dev/null 2>&1 && ! helm template t "$1" -f "$2" --set-json "pool.size={\"cpu\":{}}" >/dev/null 2>&1' _ "$CHART" "$EXAMPLE"
    t "limits.size and limits.pods exist in values.yaml" test "$(yq '.limits.pods' "$CHART/values.yaml")" = 20 -a "$(yq '.limits.size.cpu.limit' "$CHART/values.yaml")" = 2
    for code in 'limits.size' 'limits.pods' '`namespaces`' '`scopes`' '`render_namespace`' '`grants.writers`' '`grants.modes`' '`crds.install`' '`stamper.enabled`' '`stamper.identity`'; do
        t "the Values added bullet names ${code}" grep -qF -- "${code}" <<<"$(grep '^- Values added:' <<<"$text")"
    done
    t "the keys named in the Values added bullet exist in values.yaml" test "$(yq '[.limits, .namespaces, .scopes, .render_namespace, .grants.writers, .grants.modes, .crds.install, .stamper.enabled, .stamper.identity] | map(. == null) | any' "$CHART/values.yaml")" = false
    t "it says that network_check.enabled was true and is false, outside the Removed bullet" test "$(grep -cF 'Default changed (from `true`): `network_check.enabled` is `false` by default, and the network check needs `operator.enabled`.' <<<"$text")" -eq 1 -a "$(grep '^- Removed:' <<<"$text" | grep -c 'network_check')" -eq 0 -a "$(yq '.network_check.enabled' "$CHART/values.yaml")" = false
    t "it says that the per-namespace policies {namespace}-pod are gone" grep -qF 'The per-namespace pod policies and bindings `{namespace}-pod` of 0.3.0 are gone: one policy `br-sandbox-pod` serves every managed namespace.' <<<"$text"
    t "no render holds a policy named after a namespace" jqt keeper '[.[] | select(.kind == "ValidatingAdmissionPolicy" or .kind == "ValidatingAdmissionPolicyBinding") | .metadata.name | select(endswith("-pod") and . != "br-sandbox-pod")] | length == 0'
    t "it states the pod policy at an update, with the test file" grep -qF 'In 0.4.0 the rules that read the `SandboxPool` judge a creation only (`BR_SANDBOX_IMAGE`, and the bound of the agent size by the pool in `BR_SANDBOX_RESOURCES`' <<<"$text"
    t "it says that BR_SANDBOX_IMMUTABLE compares the images, the init containers, the ephemeral containers and serviceAccountName, and that pods/resize is matched" grep -qF '`BR_SANDBOX_IMMUTABLE` now also compares the images, the init containers, the ephemeral containers and `serviceAccountName`. The binding `br-sandbox-pod-update` matches the update of `pods`, `pods/ephemeralcontainers` and `pods/resize`, and has no `paramRef`.' <<<"$text"
    t "the rendered update binding matches pods, pods/ephemeralcontainers and pods/resize on UPDATE and has no paramRef" jqt keeper '[.[] | select(.kind == "ValidatingAdmissionPolicyBinding" and .metadata.name == "br-sandbox-pod-update")] | length == 1 and (.[0].spec | has("paramRef") | not)'
    t "the rendered policy matches pods/resize and pods/ephemeralcontainers on UPDATE" jqt keeper '[.[] | select(.kind == "ValidatingAdmissionPolicy" and .metadata.name == "br-sandbox-pod") | .spec.matchConstraints.resourceRules[] | select(.operations == ["UPDATE"]) | .resources[]] | contains(["pods/resize", "pods/ephemeralcontainers"])'
    t "the rendered immutable rule compares the init containers, the ephemeral containers and the account name" jqt keeper '[.[] | select(.kind == "ValidatingAdmissionPolicy" and .metadata.name == "br-sandbox-pod") | .spec.validations[] | select(.message | startswith("BR_SANDBOX_IMMUTABLE")) | .expression | (contains("object.spec.initContainers == oldObject.spec.initContainers") and contains("object.spec.ephemeralContainers == oldObject.spec.ephemeralContainers") and contains("object.spec.serviceAccountName == oldObject.spec.serviceAccountName") and contains("object.spec.containers == oldObject.spec.containers"))] == [true]'
    for code in BR_SANDBOX_NOTHING_TO_RENDER 'BR_SANDBOX_OPERATOR_PART_REQUIRED{key=network_check}` and `{key=stamper}' 'BR_SANDBOX_OPERATOR_SETTING_REMOVED{key=pools}' 'BR_SANDBOX_NO_SCOPE{namespace=...}' 'BR_SANDBOX_SCOPES_OVERLAP{scope=...,other=...}' 'BR_SANDBOX_MODE_UNKNOWN{namespace=...,mode=...}' 'BR_SANDBOX_MODE_NOT_STAMPED{namespace=...,mode=...}' BR_SANDBOX_STAMPER_NO_SCOPES 'BR_SANDBOX_STAMPER_NOT_A_WRITER{identity=...}' 'BR_SANDBOX_STAMPER_RULE_NAME_TOO_LONG{rule=...}'; do
        t "the Render faults bullet names ${code}" grep -qF -- "${code}" <<<"$(grep '^- Render faults, new in 0.4.0' <<<"$text")"
        t "the template of the chart raises ${code%%\{*}" grep -rqF -- "\"${code%%\{*}" "$CHART/templates"
    done
    for code in ALLOW_EMPTY ALLOW_MODE CREDENTIAL_SET_MODE EGRESS_DISABLED NAME_TOO_LONG PROXY_ADDRESS_DUPLICATE RUNNER_IS_POD_IDENTITY SHARED_NAMESPACE; do
        t "the CHANGELOG names the parameters that the templates give BR_SANDBOX_${code}, each key" test -n "$(grep -rhoE "BR_SANDBOX_${code}\{[a-z_]+=%s(,[a-z_]+=[^,}]+)*\}" "$CHART/templates" | sed -E 's/=[^,}]+/=.../g' | sort -u)" -a -z "$(grep -rhoE "BR_SANDBOX_${code}\{[a-z_]+=%s(,[a-z_]+=[^,}]+)*\}" "$CHART/templates" | sed -E 's/=[^,}]+/=.../g' | sort -u | while read -r signature; do grep -qF "$signature" <<<"$text" || echo "$signature"; done)"
    done
    t "the CHANGELOG says that the namespace name, the pool_id and the keys allow, credential_set and proxy moved" grep -qF 'the name of a sandbox namespace was `{installation.namespace_prefix}-{client}-{mode}` and is now `namespaces[].name`; the `pool_id` of the adapter document was `{client}-{mode}` and is now the name of the namespace' <<<"$text"
    t "the CHANGELOG says that MISSING_VALUE of clients modes is gone, and the template no longer holds it" test "$(grep -cF 'is gone with `clients`' <<<"$text")" -eq 1 -a "$(grep -rc 'clients\.%s\.modes' "$CHART/templates" | grep -vc ':0$')" -eq 0
    t "the entry of namespaces in the schema carries allow, credential_set and proxy" test "$(jq -r '.definitions.namespace.properties | has("allow") and has("credential_set") and has("proxy")' "$CHART/values.schema.json")" = true
    fails_with 'BR_SANDBOX_MODE_UNKNOWN{namespace=sbx-alpha-x,mode=bogus}' -f "$EXAMPLE" --set-json 'namespaces=[{"name":"sbx-alpha-x","mode":"bogus"}]'
    t "the CHANGELOG names the test file of the policy model" grep -qF 'Tested offline with the policy model (`test-sandbox-chart-pod-policy.sh`)' <<<"$text"
}

check_the_readme_lists_the_stamper_values_the_faults_and_the_policies() {
    section "the README values table, error list and render table hold the stamper, its faults and the three policies"
    local readme code name
    readme="$(cat "$CHART/README.md")"
    t "the values table has the row of stamper.enabled and stamper.identity, with the defaults of values.yaml" grep -qF "| \`stamper.{enabled,identity}\` | \`false\`, \`$(yq '.stamper.identity' "$CHART/values.yaml")\` |" <<<"$readme"
    t "the row says that the identity must be in grants.writers and that the stamper needs operator.enabled" grep -qF 'it must be in `grants.writers`, else `BR_SANDBOX_STAMPER_NOT_A_WRITER{identity=...}`; the chart does not add it.' <<<"$readme"
    for code in 'BR_SANDBOX_OPERATOR_PART_REQUIRED{key=network_check}` and `{key=stamper}' BR_SANDBOX_MODE_NOT_STAMPED BR_SANDBOX_STAMPER_NO_SCOPES BR_SANDBOX_STAMPER_NOT_A_WRITER BR_SANDBOX_STAMPER_RULE_NAME_TOO_LONG; do
        t "the render error list holds ${code}" grep -qF -- "${code}" <<<"$(grep '^Render errors:' <<<"$readme")"
    done
    t "every fault raised by a template appears in the README" test -z "$(grep -rhoE 'fail[^}]*"BR_SANDBOX_[A-Z_]+' "$CHART/templates" | grep -oE 'BR_SANDBOX_[A-Z_]+' | sort -u | while read -r code; do grep -qF "$code" "$CHART/README.md" || echo "$code"; done)"
    for name in $(jq -r '[.[] | select(.kind == "ValidatingAdmissionPolicy" or .kind == "ValidatingAdmissionPolicyBinding" or (.kind == "ConfigMap" and .metadata.name == "br-sandbox-grants")) | .metadata.name] | unique[]' "$WORK/keeper.json"); do
        t "the README names the rendered object ${name} in the table of a render" grep -qF "\`${name}\`" <<<"$(sed -n '/^## What a render holds/,/^## Layout/p' "$CHART/README.md")"
    done
    t "the intro of the README names the three policies and the grants" grep -qF 'the admission policies `br-sandbox-pod`, `br-sandbox-namespace` and `br-sandbox-fence` with their bindings, the ConfigMap `br-sandbox-grants`' <<<"$readme"
    t "the README no longer says that the admission policy and its two bindings are the cluster-scoped set" test "$(grep -cF 'the admission policy and its two bindings' <<<"$readme")" -eq 0
    t "the README says that the three policies, their four bindings and the grants are rendered once" grep -qF 'the three admission policies, their four bindings and the ConfigMap `br-sandbox-grants` are rendered once' <<<"$readme"
    t "the render holds three policies and four bindings" jqt keeper '([.[] | select(.kind == "ValidatingAdmissionPolicy")] | length == 3) and ([.[] | select(.kind == "ValidatingAdmissionPolicyBinding")] | length == 4)'
    t "the README says the keeper image is named by the fixtures, not tested with" test "$(grep -cF 'that this chart is tested with is the image' <<<"$readme")" -eq 0 -a "$(grep -cF 'that the fixtures of this chart name is the image' <<<"$readme")" -eq 1
}

check_the_install_names_the_required_fields_of_the_pool() {
    section "INSTALL.md: keeper 0.2.0 requires image, size, minReplicas and maxReplicas in a SandboxPool"
    t "INSTALL.md says that keeper 0.2.0 also requires size, minReplicas and maxReplicas and what happens without them" grep -qF 'but keeper 0.2.0 also requires `size`, `minReplicas` and `maxReplicas` in a `SandboxPool`: a resource without them is `InvalidSpec` and gets no pool' "$CHART/INSTALL.md"
    t "the keeper README lists the four fields as required" grep -qF '`image`, `size`, `minReplicas` and `maxReplicas` are required' "$ROOT/crates/br-sandbox-keeper/README.md"
    t "the SandboxPool example of INSTALL.md holds the four fields" test "$(install_block 4 | yq -o=json -I=0 '.' | jq '.spec | has("image") and has("size") and has("minReplicas") and has("maxReplicas")')" = true
}

check_the_pod_security_labels_are_stated_as_conditional() {
    section "Pod Security labels: rendered on a sandbox namespace only with render_namespace, set by the owner otherwise"
    local namespace grants
    render ps_off -f "$EXAMPLE" -f "$OPERATOR_VALUES" --set render_namespace=false
    t "with render_namespace false no sandbox namespace is rendered, and the system namespace carries the labels" jqt ps_off '([.[] | select(.kind == "Namespace" and .metadata.labels["br.sandbox/managed"] == "true")] | length == 0) and ([.[] | select(.kind == "Namespace" and .metadata.name == "sbx-system") | .metadata.labels["pod-security.kubernetes.io/enforce"]] == ["baseline"])'
    t "with render_namespace true each sandbox namespace carries the three labels" jqt keeper '[.[] | select(.kind == "Namespace" and .metadata.labels["br.sandbox/managed"] == "true") | .metadata.labels | select(.["pod-security.kubernetes.io/enforce"] == "baseline" and .["pod-security.kubernetes.io/warn"] == "restricted" and .["pod-security.kubernetes.io/audit"] == "restricted")] | length == 4'
    t "no admission policy of the chart and no stamper rule reads or sets a Pod Security label" test "$(jq -c '[.[] | select(.kind == "ValidatingAdmissionPolicy" or .kind == "ClusterPolicy")]' "$WORK/keeper.json" "$WORK/stamper.json" | grep -c 'pod-security')" -eq 0
    t "the Layout table says that the sandbox namespace gets the labels only with render_namespace, and the owner sets them otherwise" grep -qF 'only with `render_namespace: true`; otherwise the owner of the namespace sets the labels (no policy, no stamper and no fence part of the chart sets them)' "$CHART/README.md"
    t "Constants, not keys says the same" grep -qF 'with `render_namespace: true`, on the sandbox namespaces; otherwise the owner of the sandbox namespace sets them)' "$CHART/README.md"
    t "INSTALL.md says that the owner sets them when the project makes the Namespace" grep -qF 'The chart renders the Pod Security labels of a sandbox namespace only with `render_namespace: true`. Here the project makes the Namespace, so its owner sets them' "$CHART/INSTALL.md"
    namespace="$(install_block 3 | yq -o=json -I=0 '.')"
    grants="$(grants_of ex)"
    t "the Namespace example of INSTALL.md carries the three labels" test "$(jq -c '.metadata.labels | [.["pod-security.kubernetes.io/enforce"], .["pod-security.kubernetes.io/warn"], .["pod-security.kubernetes.io/audit"]]' <<<"$namespace")" = '["baseline","restricted","restricted"]'
    t "the policy model admits the Namespace without the labels: nothing requires them" test "$(ns_verdict ex CREATE "$(jq -c 'del(.metadata.labels["pod-security.kubernetes.io/enforce"], .metadata.labels["pod-security.kubernetes.io/warn"], .metadata.labels["pod-security.kubernetes.io/audit"])' <<<"$namespace")" null "$PROJECT_USER" "$grants")" = admit
}

check_the_documents_name_rules_by_code_and_keep_no_stale_text() {
    section "the documents name rules by code, and hold no stale key or earlier upgrade path"
    t "no README, POLICIES, LIMITS, STAMPER or INSTALL sentence numbers a rule" test "$(cat "$CHART/README.md" "$CHART/POLICIES.md" "$CHART/LIMITS.md" "$CHART/STAMPER.md" "$CHART/INSTALL.md" | grep -cE '\b[Rr]ules? [0-9]+')" -eq 0
    t "the README names the non-root rule by its code where it describes the probe pod and the check exception" test "$(grep -cF 'the rule `BR_SANDBOX_RUN_AS_NON_ROOT` of the admission policy lets it through' "$CHART/README.md")" -eq 1 -a "$(grep -cF 'so `BR_SANDBOX_RUN_AS_NON_ROOT` admits them by the ServiceAccount' "$CHART/README.md")" -eq 1
    t "the README no longer lists the pool keys among the keys of the keeper document only" test "$(grep -cF 'the pool keys' "$CHART/README.md")" -eq 0
    t "the keeper document holds no pool key" jqt keeper '[.[] | select(.kind == "ConfigMap" and .metadata.name == "br-sandbox-keeper-config") | .data["config.json"] | fromjson | has("pools") or has("floor") or has("max_sandboxes")] == [false]'
}

check_the_documents_state_what_a_cluster_run_showed() {
    section "INSTALL.md, LIMITS.md and POLICIES.md: the order of the fence part, the restored binding, and who refused a project write"
    t "INSTALL.md says that a namespace before its fence part makes the keeper log forbidden errors until the RoleBinding arrives" grep -qF 'the keeper logs forbidden list and watch errors about once a second until the RoleBinding `br-sandbox-keeper` of the fence part arrives, and then it recovers' "$CHART/INSTALL.md"
    t "INSTALL.md and LIMITS.md say that a restored binding needs --force-conflicts at the next upgrade" test "$(grep -cF 'the next `helm upgrade` of the operator release fails on a server-side-apply conflict and needs `--force-conflicts`' "$CHART/INSTALL.md" "$CHART/LIMITS.md" | grep -c ':1$')" -eq 2
    t "INSTALL.md and POLICIES.md say that RBAC refused the project write in a reported run, and that the policy refusal is not proved on a cluster" test "$(grep -cF 'refused by RBAC' "$CHART/INSTALL.md" "$CHART/POLICIES.md" | grep -c ':1$')" -eq 2 -a "$(grep -cF 'not by `BR_SANDBOX_FENCE`' "$CHART/INSTALL.md" "$CHART/POLICIES.md" | grep -c ':1$')" -eq 2
    render route_fence_docs -f "$EXAMPLE" -f "$CHART/ci/fence-values.yaml"
    t "the keeper RoleBinding named in INSTALL.md is rendered by the fence part" jqt route_fence_docs '[.[] | select(.kind == "RoleBinding" and .metadata.name == "br-sandbox-keeper")] | length > 0'
}

check_the_public_documents_name_no_private_material() {
    section "the documents of the chart name no private repository, path or distribution group"
    t "no document of the chart cites a path of a cluster repository, a README of another repository or a file of a cluster install" test "$(all_chart_text | grep -ciE 'clusters/[a-z]+/|\.application\.yaml|of the `[A-Za-z]+` repository|README of `[A-Za-z]+`|comment of `')" -eq 0
    t "no document of the chart names the administrator group of a distribution" test "$(all_chart_text | grep -ciE 'system:masters|administrator is a user')" -eq 0
    t "no file of the chart holds an absolute path of a developer machine" test "$(grep -rlE '/Users/|/home/[a-z]+/' "$CHART" | wc -l | tr -d ' ')" -eq 0
    t "STAMPER.md keeps the facts in generic words: the default network policy, the labelling policy and the rights of the policy engine" test "$(grep -cF 'The cluster default network policy.' "$CHART/STAMPER.md")" -eq 1 -a "$(grep -cF 'The scope labelling policy.' "$CHART/STAMPER.md")" -eq 1 -a "$(grep -cF 'Rights of Kyverno.' "$CHART/STAMPER.md")" -eq 1
}

check_the_stamper_texts_state_the_rights_and_the_one_maker_rule() {
    section "STAMPER.md, INSTALL.md and LIMITS.md: the rights of the policy engine are needed, one namespace has one maker"
    local maker off proof trust refusal file
    maker='One namespace has one maker of its fence: a fence release, or the stamper. The stamper acts on every scope of the scope table, and also on namespaces that exist. Do not turn the stamper on while a fence release fences a namespace of a scope of the table. The effect is not tested: the stamper can take the objects, overwrite them, or delete them when it is turned off.'
    off='Not tested: to turn the stamper off, or to remove the policy engine, while stamped namespaces exist. The policy engine can then delete the fence objects that it made; a namespace with no fence gets no pool. Remove the pools first.'
    proof='The automatic stamping passed once on a test cluster with the policy engine (reported by the operator of that cluster; no record in this repository), for one namespace in mode none. Not proved: the platform cluster and the rights of the policy engine there, a second project at the same time, mode full, a namespace already fenced by the fence release, a policy removal while stamped namespaces exist.'
    trust='With these rights, a person who takes control of the background controller of the policy engine can write service accounts, quotas, limit ranges, ConfigMaps, RoleBindings and NetworkPolicies in every namespace, and can bind the two ClusterRoles of the sandbox there.'
    refusal='validate-policy.kyverno.svc denied ... kyverno-background-controller requires permissions create,update,delete for resource v1/ServiceAccount in namespace {{ request.object.metadata.name }}'
    for file in STAMPER.md INSTALL.md LIMITS.md; do
        t "${file} carries the one-maker sentences and the policy-removal sentences" has_all "$CHART/$file" "$maker" "$off"
        t "${file} carries the trust sentence on the rights of the policy engine" grep -qF "$trust" "$CHART/$file"
    done
    t "STAMPER.md and LIMITS.md carry the proof words of the stamper" test "$(grep -cF "$proof" "$CHART/STAMPER.md" "$CHART/LIMITS.md" | grep -c ':1$')" -eq 2
    t "STAMPER.md and INSTALL.md give the refusal message, and say that a server-side dry run does not show it" test "$(grep -cF "$refusal" "$CHART/STAMPER.md" "$CHART/INSTALL.md" | grep -c ':1$')" -eq 2 -a "$(grep -cF 'dry-run=server' "$CHART/STAMPER.md" "$CHART/INSTALL.md" | grep -c ':[1-9]')" -eq 2
    t "STAMPER.md says that the rights are needed and not inferred, the order, that the chart does not render the ClusterRole, and how to leave the failed revision" test "$(grep -cF 'Needed, not inferred, on one cluster' "$CHART/STAMPER.md")" -eq 1 -a "$(grep -cF 'Order: apply the rights first, then turn the stamper on.' "$CHART/STAMPER.md")" -eq 1 -a "$(grep -cF 'The chart does not render this ClusterRole: a right of the policy engine is a grant of the owner of the platform.' "$CHART/STAMPER.md")" -eq 1 -a "$(grep -cF '`helm rollback RELEASE REVISION`' "$CHART/STAMPER.md")" -eq 1
    t "no template of the chart renders a ClusterRole for the policy engine" test "$(grep -rc 'aggregate-to-background-controller' "$CHART/templates" | grep -vc ':0$')" -eq 0
    t "the ClusterRole of STAMPER.md names the five kinds that the Kyverno report covers, the networkpolicies rule, the verbs and the bind on the two ClusterRoles that the stamped RoleBindings name" test "$(awk '/^```yaml/{on=1;next} /^```/{on=0} on' "$CHART/STAMPER.md" | yq -o=json -I=0 '[.kind, .metadata.labels["rbac.kyverno.io/aggregate-to-background-controller"], (.rules[0].resources | sort), (.rules[1].resources), (.rules[2].verbs), (.rules[2].resourceNames | sort), (.rules[0].verbs | contains(["create", "update", "delete"])), (.rules[1].verbs | contains(["create", "update", "delete"])), .rules[3].apiGroups, .rules[3].resources, (.rules[3].verbs | contains(["create", "update", "delete"])), (.rules | length)]')" = '["ClusterRole","true",["configmaps","limitranges","resourcequotas","serviceaccounts"],["rolebindings"],["bind"],["br-sandbox-controller","br-sandbox-runner"],true,true,["networking.k8s.io"],["networkpolicies"],true,4]'
    t "the two ClusterRoles of the example are the two that the stamper binds in the namespaces" test "$(jq -r '[.[] | select(.kind == "ClusterPolicy") | .spec.rules[] | .generate.data.roleRef.name? // empty] | unique | join(",")' "$WORK/stamper.json")" = br-sandbox-controller,br-sandbox-runner
    t "STAMPER.md and INSTALL.md give the command that lists the managed namespaces" test "$(grep -cF 'kubectl get namespaces -l br.sandbox/managed=true' "$CHART/STAMPER.md" "$CHART/INSTALL.md" | grep -c ':1$')" -eq 2
    t "STAMPER.md says that a project identity can add the mode label alone on a namespace that is not managed" grep -qF 'A project identity can add the label `br.sandbox/mode` alone on a namespace that is not managed' "$CHART/STAMPER.md"
    t "the stamper renders one rule for every key of the scope table, with generateExisting and synchronize" jqt stamper '[.[] | select(.kind == "ClusterPolicy") | .spec.rules[] | .generate | select(. != null) | [.generateExisting, .synchronize]] | length > 0 and all(. == [true, true])'
    t "no document names the rights of the policy engine as inferred only" test "$(cat "$CHART/STAMPER.md" "$CHART/INSTALL.md" "$CHART/LIMITS.md" | grep -ciE 'inferred from the objects above')" -eq 0
}

check_limits_state_the_taken_over_keeper_the_placement_and_the_image_bound() {
    section "LIMITS.md and README.md: a person who takes control of the keeper, placement and priority, the Pod Security labels, the image bound"
    local placement open_words
    placement='The pod policy does not judge the placement and the priority of a pod (`nodeName`, tolerations, affinity, `priorityClassName`, `schedulerName`), and it does not refuse a container with another name. A person who takes control of the keeper, or of an identity that creates pods in a sandbox namespace, can choose the node of a pod, make a pod tolerate a taint, ask a priority class that exists in the cluster, and add a container of the tools repository. The effect can go out of the namespace: a pod of another project can be removed for a pod of higher priority. The quota, the network policy and the other rules of the pod policy still hold.'
    open_words='Open for the next chart version: two traps for a rule (the API server sets defaults for tolerations, the scheduler name and possibly a priority before the policy reads the pod; a value of the chart for one of these fields must stay allowed). TO DECIDE (owner of the platform): rules in the next chart version, or a control of the platform on these fields until then.'
    t "LIMITS.md carries the placement paragraph and the open words" has_all "$CHART/LIMITS.md" "$placement" "$open_words"
    t "no rule of the pod policy reads nodeName, tolerations, affinity, priorityClassName or schedulerName" jqt ex '[.[] | select(.kind == "ValidatingAdmissionPolicy" and .metadata.name == "br-sandbox-pod") | .spec.validations[].expression | select(test("nodeName|tolerations|affinity|priorityClassName|priority|schedulerName"))] | length == 0'
    t "LIMITS.md says what a person who takes control of the keeper can start, and what still holds" grep -qF 'A person who takes control of either can start in a sandbox namespace pods of the image of the pool with another command, other environment variables, another DNS setting, another node selector, another pull policy, another grace period, another `runAsGroup`, another `readOnlyRootFilesystem`, other exact init-container resources, `envFrom` or ConfigMap volumes by name (any ConfigMap of the namespace) and `hostAliases`: no rule judges them. The network policy, the quota, the image rule, the service-account rule and the host and privilege rules still hold.' "$CHART/LIMITS.md"
    t "the keeper has no pods create right in the controller ClusterRole, and the runner has" jqt ex '([.[] | select(.kind == "ClusterRole" and .metadata.name == "br-sandbox-controller") | .rules[] | select((.resources | index("pods")) and (.verbs | index("create")))] | length == 0) and ([.[] | select(.kind == "ClusterRole" and .metadata.name == "br-sandbox-runner") | .rules[] | select((.resources | index("pods")) and (.verbs | index("create")))] | length == 1)'
    t "LIMITS.md and README.md say that the keeper has no pods create right and that the runner creates pods" test "$(grep -cF 'The keeper has no `pods` create right' "$CHART/LIMITS.md" "$CHART/README.md" | grep -c ':1$')" -eq 2
    t "LIMITS.md and README.md say that the pod policy does not depend on the Pod Security labels and that the owner sets them as a second barrier" test "$(grep -cF 'The pod policy does not depend on the Pod Security labels of the namespace. The owner of a namespace that the chart does not render should set them as a second barrier.' "$CHART/LIMITS.md" "$CHART/README.md" | grep -c ':1$')" -eq 2
    t "README.md, POLICIES.md and LIMITS.md say that the image of the other containers is a repository bound, any tag or digest passes" test "$(grep -cE 'repository bound, not a constant|any tag or digest of those repositories passes' "$CHART/README.md" "$CHART/POLICIES.md" "$CHART/LIMITS.md" | grep -c ':[1-9]')" -eq 3
    t "the rendered rule on images compares the other containers to a repository prefix with a colon or an at sign, never to the digest of the chart" jqt ex '[.[] | select(.kind == "ValidatingAdmissionPolicy" and .metadata.name == "br-sandbox-pod") | .spec.validations[] | select(.message | startswith("BR_SANDBOX_IMAGE:")) | .expression | (contains("c.image.startsWith(p + '"'"':'"'"')") and contains("c.image.startsWith(p + '"'"'@'"'"')") and (contains("sha256:") | not))] == [true]'
    t "no document calls the image of the other containers a platform constant" test "$(all_chart_text | grep -ciE 'image[^.]{0,60}platform constant|platform constant[^.]{0,60}image')" -eq 0
}
